(() => { const c=window.ATLAS_CONTENT; document.querySelectorAll('[data-checkout="principal"]').forEach(a=>a.href=c.checkout.principal);document.querySelectorAll('[data-checkout="completo"]').forEach(a=>a.href=c.checkout.completo);document.querySelectorAll('[data-loop]').forEach(t=>{[...t.children].forEach(x=>{const clone=x.cloneNode(true);clone.setAttribute('aria-hidden','true');t.append(clone);});t.setAttribute('aria-live','off');});document.querySelectorAll('[data-play-video]').forEach(button=>button.addEventListener('click',()=>{const video=document.getElementById(button.dataset.playVideo);if(video){video.scrollIntoView({block:'center',behavior:'smooth'});video.play().catch(()=>video.focus());}})); })();

